import csv,json,os
from decimal import Decimal,ROUND_HALF_UP
rows=list(csv.DictReader(open('/inputs/colors.csv',newline='',encoding='utf-8-sig')))
def lum(h):
    h=h.lstrip('#');out=[]
    for i in (0,2,4):
        c=int(h[i:i+2],16)/255
        out.append(c/12.92 if c<=0.04045 else ((c+0.055)/1.055)**2.4)
    return 0.2126*out[0]+0.7152*out[1]+0.0722*out[2]
def cr(a,b):
    la,lb=lum(a),lum(b);hi,lo=max(la,lb),min(la,lb)
    return (hi+0.05)/(lo+0.05)
fails=[];total=0
for r in rows:
    for role,bg in (('body_text','Background (Hex)'),('cta_label','CTA (Hex)')):
        total+=1
        x=cr(r['Text (Hex)'],r[bg])
        if x<4.5:
            fails.append({'palette_id':int(r['No']),'role':role,
              'contrast_ratio':str(Decimal(repr(x)).quantize(Decimal('0.0001'),ROUND_HALF_UP))})
fails.sort(key=lambda f:(f['palette_id'],f['role']))
out={'standard':'WCAG-2.2-AA-normal-text','threshold':4.5,'total_palettes':len(rows),
     'total_pairs':total,'passing_pairs':total-len(fails),'failing_pairs':len(fails),'failures':fails}
os.makedirs('/work',exist_ok=True)
json.dump(out,open('/work/palette-contrast.json','w'),indent=2)
